package com.jian.scrcpy.protocol;import io.netty.buffer.ByteBuf;import io.netty.channel.ChannelHandlerContext;import io.netty.handler.codec.MessageToByteEncoder;import java.nio.charset.StandardCharsets;import static com.jian.scrcpy.protocol.ControlMessages.*;
public final class ControlMessageEncoder extends MessageToByteEncoder<Message>{private static byte[] utf8(String s,int max){var b=s.getBytes(StandardCharsets.UTF_8);if(b.length<=max)return b;int n=max;while(n>0&&(b[n]&0xC0)==0x80)n--;return java.util.Arrays.copyOf(b,n);}private static void pos(ByteBuf o,Position p){o.writeInt(p.x()).writeInt(p.y()).writeShort(p.screenWidth()).writeShort(p.screenHeight());}private static int u16(float v){return Math.round(Math.max(0,Math.min(1,v))*65535f);}private static int i16(float v){v=Math.max(-1,Math.min(1,v));return Math.round(v*32767f);}
protected void encode(ChannelHandlerContext c,Message m,ByteBuf o){switch(m){case Keycode x->o.writeByte(0).writeByte(x.action()).writeInt(x.keycode()).writeInt(x.repeat()).writeInt(x.metaState());case Text x->{var b=utf8(x.text(),300);o.writeByte(1).writeInt(b.length).writeBytes(b);}case Touch x->{o.writeByte(2).writeByte(x.action()).writeLong(x.pointerId());pos(o,x.position());o.writeShort(u16(x.pressure())).writeInt(x.actionButton()).writeInt(x.buttons());}case Scroll x->{o.writeByte(3);pos(o,x.position());o.writeShort(i16(x.hscroll()/16f)).writeShort(i16(x.vscroll()/16f)).writeInt(x.buttons());}case Simple x->o.writeByte(x.type().ordinal());case ClipboardSet x->{var b=utf8(x.text(),(1<<18)-14);o.writeByte(9).writeLong(x.sequence()).writeByte(x.paste()?1:0).writeInt(b.length).writeBytes(b);}case DisplayPower x->o.writeByte(10).writeByte(x.on()?1:0);case StartApp x->{var b=utf8(x.name(),255);o.writeByte(16).writeByte(b.length).writeBytes(b);}case ResizeDisplay x->o.writeByte(21).writeShort(x.width()).writeShort(x.height());case ScanFile x->{var b=utf8(x.path(),256);o.writeByte(22).writeInt(b.length).writeBytes(b);}}}}